head.script:
scwin.onpageload = function () {
    // 페이지 로드 시 데이터 바인딩
    scwin.loadProjectData();

    // WebSocket 연결 초기화
    scwin.initWebSocket();
};

// 프로젝트 데이터 로드 함수
scwin.loadProjectData = function() {
    console.log("프로젝트 데이터 로드 완료");
};

// ==================== WebSocket 연결 및 관리 ====================

// WebSocket 전역 변수
scwin.websocket = null;
scwin.isWebSocketConnected = false;
scwin.reconnectAttempts = 0;
scwin.maxReconnectAttempts = 5;
scwin.reconnectDelay = 3000; // 3초
scwin.wsUrls = null; // WebSocket URL 목록 저장

/**
 * WebSocket 연결 초기화
 */
scwin.initWebSocket = function() {
    debugger;
    console.log("WebSocket 연결 테스트 시작");

    // 디바운싱 타이머 변수
    scwin.debounceTimer = null;
    scwin.debounceDelay = 2000;

    console.log("현재 위치:", window.location.href);

    // 간단한 WebSocket URL
    var protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    var host = window.location.host;
    // 칸반 경로로 다시 시도 (Redis 의존성 제거 후)
    var websocketUrl = protocol + '//' + host + '/InsWebApp/kanban';

    console.log("연결 시도 URL:", websocketUrl);

    try {
        scwin.websocket = new WebSocket(websocketUrl);

        scwin.websocket.onopen = function(event) {
            console.log("WebSocket 연결 성공");
            scwin.isWebSocketConnected = true;

            // 테스트 메시지 전송
            var testMessage = {
                type: "USER_JOIN",
                userId: "test-user",
                timestamp: Date.now()
            };
            scwin.websocket.send(JSON.stringify(testMessage));
            console.log("테스트 메시지 전송:", testMessage);
        };

        scwin.websocket.onmessage = function(event) {
            console.log("=== WebSocket 메시지 수신 ===");
            console.log("서버 응답:", event.data);

            try {
                var message = JSON.parse(event.data);
                console.log("파싱된 메시지:", message);
                console.log("메시지 타입:", message.type);

                // 실제 메시지 처리 함수 호출
                scwin.handleWebSocketMessage(message);
            } catch (error) {
                console.error("메시지 파싱 오류:", error);
                console.error("파싱 실패한 데이터:", event.data);
            }
        };

        scwin.websocket.onclose = function(event) {
            console.log("WebSocket 연결 종료:", event.code, event.reason);
            scwin.isWebSocketConnected = false;
        };

        scwin.websocket.onerror = function(event) {
            console.error("WebSocket 연결 실패");
            console.error("URL:", websocketUrl);
            scwin.isWebSocketConnected = false;
        };

    } catch (error) {
        console.error("WebSocket 생성 실패:", error);
    }
};

/**
 * WebSocket 연결 성공 이벤트
 */
scwin.onWebSocketOpen = function(event) {
    console.log("=== WebSocket 연결 성공 ===");
    scwin.isWebSocketConnected = true;
    scwin.reconnectAttempts = 0;

    // 사용자 참여 메시지 전송
    scwin.sendUserJoinMessage();

    // 연결 상태 표시 (선택사항)
    scwin.updateConnectionStatus(true);
};

/**
 * WebSocket 메시지 수신 이벤트
 */
scwin.onWebSocketMessage = function(event) {
    console.log("WebSocket 메시지 수신:", event.data);

    try {
        var message = JSON.parse(event.data);
        scwin.handleWebSocketMessage(message);
    } catch (error) {
        console.error("메시지 파싱 오류:", error);
    }
};

/**
 * WebSocket 연결 종료 이벤트
 */
scwin.onWebSocketClose = function(event) {
    console.log("WebSocket 연결 종료:", event.code, event.reason);
    scwin.isWebSocketConnected = false;

    // 연결 상태 표시 업데이트
    scwin.updateConnectionStatus(false);

    // 자동 재연결 제거됨
};

// 복잡한 재시도 로직 제거됨

/**
 * WebSocket 에러 이벤트
 */
scwin.onWebSocketError = function(event) {
    console.error(" WebSocket 에러 발생:");
    console.error("  - readyState:", scwin.websocket ? scwin.websocket.readyState : 'undefined');
    console.error("  - event:", event);

    scwin.isWebSocketConnected = false;

    // 상세 에러 정보 표시
    var readyStateText = {
        0: "CONNECTING (연결 중)",
        1: "OPEN (연결됨)", 
        2: "CLOSING (연결 종료 중)",
        3: "CLOSED (연결 종료됨)"
    };

    if (scwin.websocket) {
        console.error(" WebSocket 상태:", readyStateText[scwin.websocket.readyState] || "알 수 없음");
    }
};

/**
 * 사용자 참여 메시지 전송
 */
scwin.sendUserJoinMessage = function() {
    var message = {
        type: "USER_JOIN",
        userId: "user01", // 임시 사용자 ID
        timestamp: Date.now()
    };

    scwin.sendWebSocketMessage(message);
};

/**
 * WebSocket 메시지 전송
 */
scwin.sendWebSocketMessage = function(message) {
    if (scwin.websocket && scwin.websocket.readyState === WebSocket.OPEN) {
        var jsonMessage = JSON.stringify(message);
        scwin.websocket.send(jsonMessage);
        console.log("WebSocket 메시지 전송:", jsonMessage);
    } else {
        console.warn("WebSocket 연결이 되어있지 않습니다.");
    }
};

/**
 * WebSocket 메시지 처리
 */
scwin.handleWebSocketMessage = function(message) {
    console.log("메시지 처리:", message.type);

    switch (message.type) {
        case "CONNECTION_SUCCESS":
            console.log("연결 성공:", message.message);
            break;
        case "USER_JOIN_SUCCESS":
            console.log("사용자 참여 성공:", message.message);
            break;
        case "CARD_MOVED":
        case "CARD_MOVE":
            scwin.handleCardMovedMessage(message);
            break;
        case "PONG":
            console.log("PONG 수신");
            break;
        case "ERROR":
            console.error("서버 에러:", message.message);
            break;
        default:
            console.log("알 수 없는 메시지 타입:", message.type);
    }
};

/**
 * 카드 이동 메시지 처리 (다른 사용자의 실시간 카드 이동 반영)
 */
scwin.handleCardMovedMessage = function(message) {
    console.log("=== 다른 사용자의 카드 이동 수신 ===");
    console.log("전체 메시지:", message);
    console.log("- taskId:", message.taskId, "타입:", typeof message.taskId);
    console.log("- fromBoardId:", message.fromBoardId, "타입:", typeof message.fromBoardId);
    console.log("- toBoardId:", message.toBoardId, "타입:", typeof message.toBoardId);
    console.log("- userId:", message.userId);
    console.log("- projectId:", message.projectId);
    console.log("- timestamp:", message.timestamp);

    // 테스트용: 본인이 이동한 카드도 처리 (원래는 중복 방지를 위해 무시)
    var currentUserId = scwin.getCurrentUserId();
    console.log("현재 사용자 ID:", currentUserId);
    console.log("메시지 사용자 ID:", message.userId);
    console.log("ID 비교 결과:", message.userId === currentUserId);

    if (message.userId === currentUserId) {
        console.log("🧪 [테스트 모드] 본인이 이동한 카드도 처리합니다.");
        // return; // 테스트용으로 주석 처리
    }

    // 메시지 유효성 검증
    if (!message.taskId || !message.toBoardId) {
        console.error("❌ 잘못된 카드 이동 메시지:", message);
        console.error("필수 필드 확인: taskId=", message.taskId, "toBoardId=", message.toBoardId);
        return;
    }

    console.log("✅ 메시지 유효성 검증 통과 - 카드 이동 처리 시작");

    // 실제 카드 이동 처리
    scwin.updateCardPositionFromMessage(message);
};

/**
 * 연결 상태 표시 업데이트
 */
scwin.updateConnectionStatus = function(isConnected) {
    // TODO: UI에 연결 상태 표시
    console.log("연결 상태:", isConnected ? "연결됨" : "연결 끔어짐");
};

/**
 * 카드 이동 메시지 전송
 */
scwin.sendCardMoveMessage = function(taskId, fromBoardId, toBoardId) {
    // 현재 프로젝트 ID 가져오기
    var projectId = null;
    if (scwin.currentProjectData && scwin.currentProjectData.projectId) {
        projectId = scwin.currentProjectData.projectId;
    } else {
        // 프로젝트 데이터가 없으면 URL에서 추출 시도
        var urlParams = new URLSearchParams(window.location.search);
        projectId = urlParams.get('projectId');
    }

    var message = {
        type: "CARD_MOVE",
        taskId: taskId,
        fromBoardId: fromBoardId,
        toBoardId: toBoardId,
        projectId: projectId,
        userId: scwin.getCurrentUserId(),
        timestamp: Date.now()
    };

    console.log(" 카드 이동 메시지 전송:", message);
    scwin.sendWebSocketMessage(message);
};

/**
 * 현재 사용자 ID 가져오기
 */
scwin.getCurrentUserId = function() {
    var currentUserId = null;

    try {
        // 1. 프로젝트 데이터에서 사용자 ID 가져오기
        if (scwin.currentProjectData && scwin.currentProjectData.userId) {
            currentUserId = scwin.currentProjectData.userId;
        }

        // 2. WebSquare 세션에서 가져오기
        if (!currentUserId && typeof WebSquare !== "undefined" && WebSquare.session) {
            currentUserId = WebSquare.session.getAttribute("userId") || WebSquare.session.getAttribute("userEmail");
        }

        // 3. 세션 스토리지에서 가져오기
        if (!currentUserId && typeof sessionStorage !== "undefined") {
            currentUserId = sessionStorage.getItem("userId") || sessionStorage.getItem("userEmail");
        }

        // 4. 기본값
        if (!currentUserId) {
            currentUserId = "user01"; // 임시 기본값
        }

    } catch (e) {
        console.error("사용자 ID 가져오기 실패:", e);
        currentUserId = "user01"; // 오류 시 기본값
    }

    return currentUserId;
};

/**
 * 메시지로부터 카드 위치 업데이트 (실시간 동기화 핵심 로직)
 */
scwin.updateCardPositionFromMessage = function(message) {
    console.log("=== 실시간 카드 위치 업데이트 시작 ===");

    var taskId = message.taskId;
    var fromBoardId = message.fromBoardId;
    var toBoardId = message.toBoardId;

    // 1. 이동할 카드 찾기
    var cardElement = scwin.findCardByTaskId(taskId);
    if (!cardElement) {
        console.error("카드를 찾을 수 없습니다:", taskId);
        return;
    }

    console.log("카드 찾기 성공:", cardElement);

    // 2. 타겟 보드 컨테이너 찾기
    var targetContainerId = "card_container_" + toBoardId;
    var targetContainer = null;

    try {
        targetContainer = eval(targetContainerId);
    } catch (e) {
        console.error("타겟 컨테이너 찾기 실패:", targetContainerId, e);
    }

    if (!targetContainer) {
        console.error("타겟 컨테이너를 찾을 수 없습니다:", targetContainerId);
        return;
    }

    console.log("타겟 컨테이너 찾기 성공:", targetContainer);

    // 3. 카드 이동 애니메이션 및 DOM 업데이트
    scwin.animateCardMove(cardElement, targetContainer, fromBoardId, toBoardId, taskId);

    console.log("=== 실시간 카드 위치 업데이트 완료 ===");
};

/**
 * taskId로 카드 DOM 요소 찾기 (강화된 디버깅 버전)
 */
scwin.findCardByTaskId = function(taskId) {
    console.log("=== 카드 찾기 시작 ===");
    console.log("찾을 taskId:", taskId, "타입:", typeof taskId);

    // 방법 1: data-task-id 속성으로 찾기
    console.log("방법 1: data-task-id 속성으로 검색");
    var cardElement = document.querySelector(`[data-task-id="${taskId}"]`);
    if (cardElement) {
        console.log("✅ data-task-id로 카드 찾기 성공:", cardElement);
        console.log("카드 element:", cardElement.outerHTML.substring(0, 200) + "...");
        return cardElement;
    } else {
        console.log("❌ data-task-id로 찾기 실패");
        // 디버깅: 현재 존재하는 모든 data-task-id 출력
        var allCards = document.querySelectorAll("[data-task-id]");
        console.log("현재 존재하는 카드들:", Array.from(allCards).map(card => card.getAttribute("data-task-id")));
    }

    // 방법 2: 카드 ID로 찾기 (card_taskId 형식)
    console.log("방법 2: 카드 ID로 검색");
    var cardId = "card_" + taskId;
    console.log("검색할 카드 ID:", cardId);

    var cardComponent = null;
    try {
        cardComponent = eval(cardId);
        console.log("eval 결과:", cardComponent);
        if (cardComponent && cardComponent.element) {
            console.log("✅ 카드 ID로 컴포넌트 찾기 성공:", cardComponent);
            return cardComponent.element;
        }
    } catch (e) {
        console.log("❌ eval로 카드 ID 찾기 실패:", cardId, e.message);
    }

    // 방법 3: WebSquare 컴포넌트 ID로 찾기
    console.log("방법 3: WebSquare 컴포넌트 ID로 검색");
    try {
        cardComponent = $p.getComponentById(cardId);
        console.log("$p.getComponentById 결과:", cardComponent);
        if (cardComponent && cardComponent.element) {
            console.log("✅ WebSquare ID로 카드 찾기 성공:", cardComponent);
            return cardComponent.element;
        }
    } catch (e) {
        console.log("❌ WebSquare ID로 찾기 실패:", cardId, e.message);
    }

    // 방법 4: DOM에서 직접 ID로 찾기
    console.log("방법 4: DOM에서 직접 ID로 검색");
    cardElement = document.getElementById(cardId);
    if (cardElement) {
        console.log("✅ DOM ID로 카드 찾기 성공:", cardElement);
        return cardElement;
    } else {
        console.log("❌ DOM ID로 찾기 실패:", cardId);
    }

    // 방법 5: 모든 project-card 클래스 요소에서 검색
    console.log("방법 5: 모든 project-card에서 taskId 매칭 검색");
    var allProjectCards = document.querySelectorAll(".project-card, .draggable-card");
    console.log("총 프로젝트 카드 수:", allProjectCards.length);

    for (var i = 0; i < allProjectCards.length; i++) {
        var card = allProjectCards[i];
        var cardTaskId = card.getAttribute("data-task-id");
        console.log(`카드 ${i + 1}: data-task-id="${cardTaskId}"`);

        // 문자열과 숫자 비교 모두 확인
        if (cardTaskId == taskId || cardTaskId === taskId.toString() || cardTaskId === parseInt(taskId)) {
            console.log("✅ 매칭되는 카드 발견:", card);
            return card;
        }
    }

    console.error("=== 모든 방법으로 카드를 찾을 수 없습니다 ===");
    console.error("찾으려던 taskId:", taskId);
    console.error("현재 페이지의 모든 카드 정보:");
    allProjectCards.forEach((card, index) => {
        console.error(`카드 ${index + 1}: ID=${card.id}, data-task-id=${card.getAttribute("data-task-id")}`);
    });

    return null;
};

/**
 * 카드 이동 애니메이션 및 DOM 업데이트
 */
scwin.animateCardMove = function(cardElement, targetContainer, fromBoardId, toBoardId, taskId) {
    console.log("카드 이동 애니메이션 시작:", {
        cardElement: cardElement,
        targetContainer: targetContainer,
        fromBoardId: fromBoardId,
        toBoardId: toBoardId,
        taskId: taskId
    });

    try {
        // 애니메이션 클래스 추가
        cardElement.classList.add("moving-remotely");

        // 실제 DOM 이동
        var targetElement = targetContainer.element || targetContainer;
        targetElement.appendChild(cardElement);

        // 카드의 data-board-id 업데이트
        cardElement.setAttribute("data-board-id", toBoardId);

        // 보드 카운트 업데이트
        scwin.updateBoardCardCounts(fromBoardId, toBoardId);

        // 애니메이션 완료 후 클래스 제거
        setTimeout(function() {
            cardElement.classList.remove("moving-remotely");
            console.log("카드 이동 애니메이션 완료:", taskId);

            // 이동 완료 알림 (선택사항)
            scwin.showCardMoveNotification(taskId, fromBoardId, toBoardId);
        }, 300);

        console.log("카드 DOM 이동 성공:", taskId, "->", toBoardId);

    } catch (error) {
        console.error("카드 이동 중 오류 발생:", error);

        // 오류 시 애니메이션 클래스 제거
        if (cardElement && cardElement.classList) {
            cardElement.classList.remove("moving-remotely");
        }
    }
};

/**
 * 보드별 카드 개수 업데이트
 */
scwin.updateBoardCardCounts = function(sourceBoardId, targetBoardId) {
    console.log("보드 카운트 업데이트:", sourceBoardId, "->", targetBoardId);

    // 출발 보드 카운트 감소
    if (sourceBoardId) {
        scwin.updateSingleBoardCardCount(sourceBoardId, -1);
    }

    // 목적지 보드 카운트 증가
    if (targetBoardId) {
        scwin.updateSingleBoardCardCount(targetBoardId, 1);
    }
};

/**
 * 단일 보드의 카드 개수 업데이트
 */
scwin.updateSingleBoardCardCount = function(boardId, delta) {
    var countSpanId = "grp_dynamic_" + boardId + "_count";

    try {
        var countSpan = eval(countSpanId);
        if (!countSpan) {
            countSpan = $p.getComponentById(countSpanId);
        }

        if (countSpan) {
            var currentCount = parseInt(countSpan.getValue() || "0");
            var newCount = Math.max(0, currentCount + delta);
            countSpan.setValue(newCount);

            console.log(`보드 [${boardId}] 카운트 업데이트: ${currentCount} -> ${newCount}`);
        } else {
            console.warn("카운트 스팬을 찾을 수 없습니다:", countSpanId);
        }
    } catch (error) {
        console.error("카운트 업데이트 중 오류:", countSpanId, error);
    }
};

/**
 * 보드 제목 가져오기
 */
scwin.getBoardTitle = function(boardId) {
    try {
        // dlt_boardListVo에서 보드 제목 찾기
        var boardList = dlt_boardListVo.getAllJSON();
        if (boardList && boardList.length > 0) {
            for (var i = 0; i < boardList.length; i++) {
                if (boardList[i].boardId === boardId) {
                    return boardList[i].boardTitle;
                }
            }
        }

        // 제목을 찾지 못한 경우 기본값 반환
        return boardId;
    } catch (error) {
        console.error("보드 제목 가져오기 실패:", boardId, error);
        return boardId;
    }
};

/**
 * 카드 이동 완료 알림 표시
 */
scwin.showCardMoveNotification = function(taskId, fromBoardId, toBoardId) {
    try {
        var fromTitle = scwin.getBoardTitle(fromBoardId);
        var toTitle = scwin.getBoardTitle(toBoardId);

        var message = `다른 사용자가 카드를 "${fromTitle}"에서 "${toTitle}"로 이동했습니다.`;
        console.log("������ " + message);

        // 선택사항: 화면에 토스트 알림 표시
        // scwin.showToastNotification(message, "info");

    } catch (error) {
        console.error("알림 표시 중 오류:", error);
    }
};

/**
 * 테스트용 핑 메시지 전송
 */
scwin.sendPingMessage = function() {
    var message = {
        type: "PING",
        timestamp: Date.now()
    };

    scwin.sendWebSocketMessage(message);
};

/**
 * 실시간 동기화 테스트용 함수 (디버깅용)
 */
scwin.testRealtimeSync = function() {
    console.log("=== 실시간 동기화 테스트 시작 ===");

    // 현재 카드 목록 출력
    var allCards = document.querySelectorAll("[data-task-id]");
    console.log("현재 페이지의 카드 수:", allCards.length);
    allCards.forEach((card, index) => {
        console.log(`카드 ${index + 1}: taskId=${card.getAttribute("data-task-id")}, boardId=${card.getAttribute("data-board-id")}`);
    });

    // 테스트 메시지 시뮬레이션
    if (allCards.length > 0) {
        var testCard = allCards[0];
        var testMessage = {
            type: "CARD_MOVED",
            taskId: testCard.getAttribute("data-task-id"),
            fromBoardId: testCard.getAttribute("data-board-id"),
            toBoardId: "BOARD_DONE_001", // 임시 목적지
            userId: "test-user", // 다른 사용자로 시뮬레이션
            timestamp: Date.now()
        };

        console.log("테스트 메시지 시뮬레이션:", testMessage);
        scwin.handleCardMovedMessage(testMessage);
    } else {
        console.log("테스트할 카드가 없습니다.");
    }

    console.log("=== 실시간 동기화 테스트 완료 ===");
};

/**
 * WebSocket 연결 테스트 함수 (디버깅용)
 */
scwin.testWebSocketConnection = function() {
    console.log(" WebSocket 연결 테스트 시작");

    if (!scwin.websocket) {
        console.error(" WebSocket이 초기화되지 않았습니다.");
        return;
    }

    console.log(" 현재 WebSocket 상태:");
    console.log("  - readyState:", scwin.websocket.readyState);
    console.log("  - url:", scwin.websocket.url);

    switch(scwin.websocket.readyState) {
        case WebSocket.CONNECTING:
            console.log(" 연결 시도 중...");
            break;
        case WebSocket.OPEN:
            console.log("✅ 연결됨 - PING 메시지 전송");
            scwin.sendPingMessage();
            break;
        case WebSocket.CLOSING:
            console.log("연결 종료 중...");
            break;
        case WebSocket.CLOSED:
            console.log(" 연결 끊어짐 - 재연결 시도");
            scwin.reconnectWebSocket();
            break;
    }
};

/**
 * 서버 연결 테스트 (HTTP 요청으로 서버 상태 확인)
 */
scwin.testServerConnection = function() {
    console.log("서버 연결 테스트 시작...");

    var testUrl = window.location.protocol + '//' + window.location.host + '/InsWebApp/board/list.pwkjson';

    fetch(testUrl, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
        },
        body: 'projectId=test'
    })
    .then(response => {
        console.log("서버 HTTP 연결 성공:", response.status);
        if (response.ok) {
            console.log(" 서버가 정상 작동 중 - WebSocket 설정 문제일 가능성");
        }
        return response.text();
    })
    .then(data => {
        console.log(" 서버 응답:", data.substring(0, 200) + "...");
    })
    .catch(error => {
        console.error(" 서버 HTTP 연결 실패:", error);
        console.error(" 서버가 실행되지 않았거나 포트가 다를 수 있습니다.");
    });
};

// 프로젝트 데이터 저장 (외부에서 호출 가능)
scwin.currentProjectData = null;

// 프로젝트 데이터 설정 함수
scwin.setProjectData = function(projectData) {
    // 중복 실행 방지
    if (scwin.isSettingProjectData) {
        console.log("이미 프로젝트 데이터를 설정 중입니다. 중복 실행을 방지합니다.");
        return;
    }

    scwin.isSettingProjectData = true;
    scwin.currentProjectData = projectData;
    console.log("프로젝트 데이터 설정됨:", projectData);

    // 프로젝트 제목 업데이트
    if (projectData && projectData.projectName) {
        txt_title.setValue(projectData.projectName);
    }

    // 프로젝트 ID를 dm_projectVo에 설정하고 보드 데이터 로드
    if (projectData && projectData.projectId) {
        console.log("프로젝트 ID로 보드 데이터 로드:", projectData.projectId);
        dm_projectVo.set("projectId", projectData.projectId);
        $p.executeSubmission("load_Board");  // 보드 데이터 로드 실행
    } else {
        console.warn("프로젝트 ID가 없어 보드 데이터를 로드할 수 없습니다:", projectData);
    }

    // 플래그 해제
    setTimeout(function() {
        scwin.isSettingProjectData = false;
    }, 100);
};

/**
 * 'Add card' 버튼 클릭 시 동적으로 카드를 생성하는 함수
 * @param {String} parentId 카드를 추가할 부모 Group(칸반 컬럼)의 ID
 */
scwin.addCard_onclick = function(parentId) {
    var parentGroup = $p.getComponentById(parentId);
    var cardId = "dyn_card_" + new Date().getTime();
    var cardOptions = {
        className: "project-card",
        style: "border-color: #2da44e; background-color: #f6ffed;"
    };
    var newCard = $p.dynamicCreate(cardId, "group", cardOptions, parentGroup);

    // 생성된 input 컴포넌트 객체를 변수에 할당합니다.
    var newInput = $p.dynamicCreate("dyn_input_" + new Date().getTime(), "input", {
        placeholder: "새 작업명을 입력하세요.",
        style: "width: 100%; height: 24px;"
    }, newCard);

    // --- 추가된 코드 ---
    // 1. 생성된 input에 onkeydown 이벤트 핸들러를 연결합니다. [cite: 5]
    newInput.bind("onkeydown", scwin.dynamicInput_onkeydown);

    // 2. 생성된 input에 바로 포커스를 줍니다.
    newInput.focus();
};

/**
 * 동적으로 생성된 Input의 키보드 이벤트(keydown)를 처리하는 함수
 * @param {Event} e 키보드 이벤트 객체
 */
scwin.dynamicInput_onkeydown = function(e) {
    // 이벤트가 발생한 컴포넌트(input) 객체
    var inputComponent = this;

    // 눌린 키의 코드 확인 (Enter: 13, ESC: 27)
    var keyCode = e.keyCode;

    if (keyCode === 13) { // Enter 키를 눌렀을 때
        let input = this.getValue();
        dm_taskVo.set("taskTitle",input);
        $c.sbm.execute("dm_taskVo");

    } else if (keyCode === 27) { // ESC 키를 눌렀을 때
        // 삭제할 대상은 input을 감싸고 있는 부모 컴포넌트(카드 그룹)입니다.
        var cardComponent = inputComponent.getParent();

        if (cardComponent) {
            // $p.remove API로 카드 컴포넌트를 화면에서 삭제합니다.
            cardComponent.remove();
        }
    }
};

